---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Launch checklist: The agent checks a design before it ships, and fixes what fails.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change launch-checklist.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './launch-checklist.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="launch-checklist" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="lcx panel">
  <div class="lcx-h"><div><b>Ready to ship pricing?</b><span class="muted lcx-st">6 checks</span></div><button class="pill primary sm lcx-run"><svg class="i xs"><use href="#i-play"/></svg>Run checks</button></div>
  <div class="lcx-bar"></div>
  <div class="lcx-list"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './launch-checklist.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Launch checklist ---------- */
.lcx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.lcx-h{display:flex;align-items:center;justify-content:space-between;gap:10px}
.lcx-h>div{display:flex;flex-direction:column}
.lcx-h b{font-weight:500;font-size:13.5px}
.lcx-st{font-size:12.5px}
.lcx-bar{display:flex;gap:3px}
.lcx-bar i{flex:1;height:5px;border-radius:3px;background:var(--dm-line);transition:background .45s var(--dm-ease)}
.lcx-bar i.ok{background:var(--dm-ok)}.lcx-bar i.bad{background:var(--dm-bad)}.lcx-bar i.run{background:var(--dm-accent-mark,var(--dm-accent));opacity:.5}
.lcx-list{display:flex;flex-direction:column}
.lcx-r{display:flex;align-items:center;gap:10px;padding:7px var(--dm-s-1);font-size:13px;border-radius:calc(10px * var(--dm-rk));min-height:38px}
.lcx-r .g{width:18px;height:18px;display:grid;place-items:center;flex:none;color:var(--dm-faint)}
.lcx-r .t{flex:1;min-width:0}
.lcx-r .d{display:block;font-size:12px;color:var(--dm-muted)}
.lcx-r.bad .d{color:var(--dm-bad)}
.lcx-r.wait .t{color:var(--dm-muted)}
.lcx-r .pill{flex:none}
.lcx-ring{width:14px;height:14px;border-radius:50%;box-shadow:inset 0 0 0 1.5px currentColor}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter, html, swap } from '../core/core.js';
DM.def('launch-checklist', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{play}', I('play','xs'));
  const C = [
    ['Contrast meets AA', null, 'All 14 text pairs pass'],
    ['Uses library tokens', '3 raw hex values in the FAQ', 'Swapped to color.text.muted'],
    ['Responsive at 375px', null, 'No overflow on 3 breakpoints'],
    ['Alt text on images', '2 icons have no label', 'Added labels from the layer names'],
    ['Links resolve', null, '12 of 12 links return 200'],
    ['Copy matches the brief', null, 'Prices and plan names match']
  ];
  const list = $('.lcx-list', r), bar = $('.lcx-bar', r), st = $('.lcx-st', r), run = $('.lcx-run', r);
  bar.innerHTML = C.map(() => '<i></i>').join(''); const segs = $$('i', bar);
  list.innerHTML = C.map(x => `<div class="lcx-r wait"><span class="g"><span class="lcx-ring"></span></span><span class="t">${x[0]}<span class="d"></span></span></div>`).join('');
  const rows = $$('.lcx-r', list);
  const G = { ok:`<span style="color:var(--dm-ok)">${I('ok')}</span>`, bad:`<span style="color:var(--dm-bad)">${I('alert')}</span>`, run:'<span class="spin"></span>' };
  function set(i, s, note){ const rw = rows[i]; rw.className = 'lcx-r ' + s; const g = $('.g', rw); g.innerHTML = G[s]; enter(g); swap($('.d', rw), note || ''); segs[i].className = s === 'run' ? 'run' : s; }
  function tally(){ const bad = rows.filter(x => x.classList.contains('bad')).length; swap(st, bad ? bad + ' to fix before shipping' : 'All clear, ready to ship'); if (!bad){ run.innerHTML = I('rocket','xs') + 'Ship it'; run.className = 'pill accent sm lcx-run'; run.onclick = () => { swap(st, 'Shipped to production'); run.disabled = true; }; } }
  run.onclick = () => c.run(async () => {
    run.disabled = true; swap(st, 'Checking');
    for (let i = 0; i < C.length; i++){
      set(i, 'run', 'Checking'); await c.wait(520 + Math.random() * 300);
      if (C[i][1]){ set(i, 'bad', C[i][1]); const f = html(`<button class="pill soft sm">${I('wand','xs')}Fix</button>`); rows[i].appendChild(f); enter(f);
        f.onclick = () => c.run(async () => { f.remove(); set(i, 'run', 'Fixing'); await c.wait(900); set(i, 'ok', C[i][2]); tally(); });
      } else set(i, 'ok', C[i][2]);
    }
    run.disabled = false; run.innerHTML = I('refresh','xs') + 'Run again'; tally();
    if (rows.some(x => x.classList.contains('bad'))) run.onclick = () => DM.mount(r.closest('.card'));
  });
  // the preview runs the checks once on its own after the entrance; the fixes are left for you
  c.auto(1300, () => { if (!run.disabled) run.click(); });
});
